       Allocate	a block of memory.; = = = = = = = = =	= = = = = = = = = =	= = = = =;;   IN:    y = ID number.;          x = attributes.;          a = number of bytes.;;  OUT:    Carry clear if handle allocated, a+x = handle.;          Carry set if error, y = error returned by Memory	Manager.;	EXPORT allocate3allocate3		;       	pha	Space for returned handle.	pha	pea 0	High word of size.	pha	Pass low word of size.	phy	Pass ID number.	phx	Pass attributes.	pha	Address doesn't matter.	pha	_NewHandle	tay	Return error code in Y.	pla	Return handle in a+x.	plx		rts		ENDP;==========================================================================;;          Do setup	for tool call.;;   IN:    a+y = handle to data area.;;  OUT:    Carry clear if no error.;          Carry set if null data pointer, y = error code.;;==========================================================================	EXPORT startupstartup	PROC	jsl IncBusyFlg	plx	Get return address.	phd	Save caller's direct page.	phb	Save caller's data page.	tcd	Switch to my direct	page.	phk	Switch to this data	bank.	plb	phx	Put return address back on stack.		rts;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = =; Entry points for function exits.;; These are shared by Window manager and Menu Manager.; Those routines starting with E expect an error code; in the y-reg.  Routines without an E do not return; an error.;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = =;;   IN:    y = error code.;	EXPORT pop0bytespop0bytes		ldy #0	; no error	EXPORT Epop0bytesEpop0bytes	ldx #0	bra shutdown	EXPORT pop2bytespop2bytes		;       	ldy #0	; no error	EXPORT Epop2bytesEpop2bytes	ldx #2	bra shutdown	EXPORT pop4bytespop4bytes		;       	ldy #0	; no error	EXPORT Epop4bytesEpop4bytes	ldx #4	bra shutdown	EXPORT pop6bytespop6bytes		;       	ldy #0	; no error	EXPORT Epop6bytesEpop6bytes	ldx #6	bra shutdown	EXPORT pop8bytespop8bytes		;       	ldy #0	; no error	EXPORT Epop8bytesEpop8bytes	ldx #8	bra shutdown	EXPORT pop10bytespop10bytes		;       	ldy #0	; no error	EXPORT Epop10bytesEpop10bytes	ldx #10	bra shutdown	EXPORT pop12bytespop12bytes		;       	ldy #0	; no error	EXPORT Epop12bytesEpop12bytes	ldx #12	bra shutdown	EXPORT pop14bytespop14bytes		ldy #0	; no error	EXPORT Epop14bytesEpop14bytes	ldx #14	bra shutdown	EXPORT pop16bytespop16bytes		;       	ldy #0	; no error	EXPORT Epop16bytesEpop16bytes	ldx #16	bra shutdown	EXPORT pop18bytespop18bytes		;       	ldy #0	; no error	EXPORT Epop18bytesEpop18bytes	ldx #18	bra shutdown	EXPORT pop26bytespop26bytes		;       	ldy #0	; no error	EXPORT Epop26bytesEpop26bytes	ldx #26	bra shutdown	EXPORT pop32bytespop32bytes		;       	ldy #0	; no error	EXPORT Epop32bytesEpop32bytes	ldx #32	;==========================================================================;	ShutDown;;  IN:     y = error code, zero if no error.;          x = number of bytes to pop.;          Startup must have been called.;;==========================================================================;	EXPORT shutdownshutdown	jsl DecBusyFlg;; --- Restore saved	parameters from startupCall --------------------------;	plb	Restore original data bank.;; --- Move return addresses over top of	input parameters -----------------;	tsc	tcd	lda 7,s	sta 7,x	lda 5,s	sta 5,x	lda 3,s	sta 3,x;; --- Adjust stact for popped parameters ---;	pld	Get original direct	page pointer.	tsc	Current stack,	phx	clc	adc 1,s	plus number of bytes popped,	tcs	equals new stack.;	tya	Return error code in Y.	cmp #1	Set carry if error.		rtl		ENDP	END